def convert_lucky_draws(apps, schema_editor):
    """
    Paid lucky draws (a stake for a chance to win) are retired. Every old campaign becomes a free, sponsored
    giveaway with referral-only entries; money people already gave is kept as Sadaqah in a crowdfunding
    campaign, and its payment records are re-pointed to the new donation rows. Old paid tickets are not carried over.
    """
    from decimal import Decimal as D

    from django.utils import timezone

    Old = apps.get_model("luckydraw", "LuckyDrawCampaign")
    OldDonation = apps.get_model("luckydraw", "MicroDonation")
    OldWinner = apps.get_model("luckydraw", "LuckyDrawWinner")
    Campaign = apps.get_model("luckydraw", "CrowdfundingCampaign")
    Donation = apps.get_model("luckydraw", "Donation")
    Giveaway = apps.get_model("luckydraw", "Giveaway")
    Winner = apps.get_model("luckydraw", "GiveawayWinner")
    Txn = apps.get_model("payments", "PaymentTransaction")
    CT = apps.get_model("contenttypes", "ContentType")
    old_ct = CT.objects.filter(app_label="luckydraw", model="microdonation").first()
    new_ct, _ = CT.objects.get_or_create(app_label="luckydraw", model="donation")
    used = set()

    def slug_for(model, text):
        from django.utils.text import slugify
        base = slugify(text)[:120] or "item"
        s, i = base, 2
        while model.objects.filter(slug=s).exists() or (model.__name__, s) in used:
            s, i = f"{base}-{i}", i + 1
        used.add((model.__name__, s))
        return s

    def clean(title):
        for bad in (" for 1 Birr", " 1 Birr", "Flash Draw", " Draw", "Win a "):
            title = title.replace(bad, " ")
        return " ".join(title.split()) or "Community"

    from apps.core import fairness

    for c in Old.objects.all():
        paid = OldDonation.objects.filter(campaign=c, status="PAID")
        crowdfund_only = "1 Birr" in c.title  # "Umrah for 1 Birr" was really a community fund
        if crowdfund_only or paid.exists():
            raised = sum((d.amount for d in paid), D("0"))
            cat = "HAJJ" if "hajj" in c.title.lower() else "UMRAH" if "umrah" in c.title.lower() else "TRAVEL"
            title = f"{clean(c.title)} Sadaqah Fund" if crowdfund_only else f"{clean(c.title)} – community fund"
            camp = Campaign.objects.create(
                title=title, slug=slug_for(Campaign, title), category=cat,
                story=(c.cause or c.description or "Help a member of our community reach their journey.")
                + "\n\nYour gift goes 100% to the cause. vacation's platform fee is shown separately at checkout.",
                image_url=c.image_url, beneficiary_name="A member of our community",
                goal_amount=max(c.prize_value or D("0"), raised, D("1000")), platform_fee_percent=D("5"),
                starts_at=c.starts_at, ends_at=None,
                status="LIVE" if c.status in ("LIVE", "SCHEDULED") else "CLOSED", is_featured=c.is_featured,
                raised_amount=raised, donations_count=paid.count(), donors_count=paid.values("user").distinct().count())
            for d in OldDonation.objects.filter(campaign=c):
                nd = Donation.objects.create(campaign=camp, user_id=d.user_id, kind="SADAQAH", amount=d.amount,
                                             fee_amount=D("0"), total_amount=d.amount, status=d.status,
                                             paid_at=d.paid_at, is_anonymous=d.is_anonymous)
                if old_ct:
                    Txn.objects.filter(content_type=old_ct, object_id=d.pk).update(
                        content_type=new_ct, object_id=nd.pk, purpose="DONATION")
        if crowdfund_only and not OldWinner.objects.filter(campaign=c).exists():
            continue
        title = clean(c.title) + " Giveaway"
        seed = c.server_seed or fairness.new_seed()
        g = Giveaway.objects.create(
            title=title, slug=slug_for(Giveaway, title),
            description=(c.description or "")
            + "\n\nThis trip is 100% paid by the sponsor. Entry is free: invite 10 friends who register on vacation "
              "and you get one entry.",
            image_url=c.image_url, sponsor_type="COMPANY", sponsor_name="vacation Travel",
            sponsor_note="Paid from vacation's marketing budget – no donations are used.",
            prize_type=c.prize_type, prize_title=c.prize_title, prize_value=c.prize_value,
            prize_package_id=c.prize_package_id, prize_equb_group_id=c.prize_equb_group_id,
            number_of_winners=c.number_of_winners, referrals_per_entry=10,
            starts_at=c.starts_at, ends_at=c.ends_at, draw_at=c.draw_at,
            status={"LIVE": "LIVE", "SCHEDULED": "SCHEDULED", "CLOSED": "CLOSED", "DRAWN": "DRAWN"}.get(c.status, "CANCELLED"),
            is_featured=c.is_featured, server_seed=seed,
            seed_commitment=c.seed_commitment if c.server_seed else fairness.commitment_for(seed),
            public_input=c.public_input, drawn_at=c.drawn_at)
        for w in OldWinner.objects.filter(campaign=c):
            Winner.objects.create(giveaway=g, user_id=w.user_id, ticket_number=w.ticket_number, rank=w.rank,
                                  prize_value=w.prize_value, voucher_code=w.voucher_code, claimed_at=w.claimed_at,
                                  claimed_booking_id=w.claimed_booking_id,
                                  claimed_equb_membership_id=w.claimed_equb_membership_id)
    Txn.objects.filter(purpose="MICRO_DONATION", content_type=new_ct).update(purpose="DONATION")


